import json
# Build input from structure: 4x4 boxes, 5x5 each (frame 4, inner 3x3), gaps 2, bg 0
colors = [[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
g = [[0]*30 for _ in range(30)]
pos = [1,8,15,22]
for bi,row in enumerate(colors):
    for bj,c in enumerate(row):
        r0,c0 = pos[bi], pos[bj]
        for i in range(5):
            for j in range(5):
                g[r0+i][c0+j] = 4 if (i in(0,4) or j in(0,4)) else c
# verify against given test input sample rows
checks = [g[1][:12], g[2][:12], g[9][:12], g[10][:12]]
print([r for r in checks])

def fill(cells, val):
    for r,c in cells: g[r][c]=val
# 3-connections
for row in (3,17): fill([(row,c) for c in (6,7,13,14,20,21)], 3)
for col in (3,24): fill([(r,col) for r in (6,7,13,14)], 3)
# 8-connections
for row in (10,24): fill([(row,c) for c in (13,14)], 8)
for col in (10,17): fill([(r,col) for r in (13,14,20,21)], 8)
print(json.dumps({"action":"submit","grid":g}))

